  onPrev: () => void;
}

export function EnvironmentStep({
  category,
  defaultValues,
  onNext,
  onPrev,
}: EnvironmentStepProps) {
  const {
    register,
    handleSubmit,
    control,
    watch,
    formState: { errors },
    setValue,
    getValues,
  } = useForm<EnvironmentMeasurementFormValues>({
    resolver: zodResolver(environmentMeasurementSchema) as any,
    defaultValues: {
      environment_condition: "",
      job_characteristic: "",
      workload_level: undefined,
      standard_value: undefined,
      measure_1: undefined,
      measure_2: undefined,
      measure_3: undefined,
      working_duration: "",
      twa_8hr: undefined,
      noise_areas:
        category === "noise"
          ? [
              {
                location_desc: "",
                min_dBA: undefined as any,
                max_dBA: undefined as any,
                avg_dBA: undefined as any,
                remark: "",
              },
            ]
          : [],
      heat_areas:
        category === "heat"
          ? [
              {
                location_desc: "",
                start_time: "",
                end_time: "",
                db_temp: undefined as any,
                wb_temp: undefined as any,
                gt_temp: undefined as any,
                wbgt_in: undefined as any,
                wbgt_type: "in" as const,
                workload: "",
                wbgt_avg: undefined as any,
                remark: "",
              },
            ]
          : [],
      light_areas:
        category === "light"
          ? [
              {
                location_desc: "",
                standard_value: 300,
                measure: undefined as any,
                remark: "",
              },
            ]
          : [],
      ...defaultValues,
    } as any,
    mode: "onTouched",
  });

  const {
    fields: noiseFields,
    append: appendNoise,
    remove: removeNoise,
  } = useFieldArray({
    control,
    name: "noise_areas" as never,
  });

  const {
    fields: heatFields,
    append: appendHeat,
    remove: removeHeat,
  } = useFieldArray({
    control,
    name: "heat_areas" as never,
  });

  const {
    fields: lightFields,
    append: appendLight,
    remove: removeLight,
  } = useFieldArray({
    control,
    name: "light_areas" as never,
  });

  const [average, setAverage] = useState<number | null>(null);

  const watchedLightAreas = watch("light_areas");
  const heatErrors = errors.heat_areas as any;

  const standards = getEnvironmentStandards(category);

  useEffect(() => {
    if (category !== "light" && standards.length === 1) {
      setValue("standard_value", standards[0].value, { shouldValidate: true });
    }
  }, [standards, setValue, category]);

  useEffect(() => {
    if (category === "light" && watchedLightAreas) {
      const vals = watchedLightAreas
        .map((a: any) => a?.measure)
        .filter(
          (v: any) =>
            v !== undefined && v !== "" && v !== null && !isNaN(Number(v)),
        );
      if (vals.length > 0) {
        const sum = vals.reduce(
          (acc: number, curr: number) => acc + Number(curr),
          0,
        );
        setAverage(Number((sum / vals.length).toFixed(2)));
      } else {
        setAverage(null);
      }
    } else {
      setAverage(null);
    }
  }, [category, watchedLightAreas]);

  const unitLabel =
    category === "light" ? "Lux" : category === "noise" ? "dBA" : "°C";

  const noiseErrors = errors.noise_areas as any;
  const lightErrors = errors.light_areas as any;

  const calculateAndSetWBGT = (index: number, newType?: string) => {
    const currentValues = getValues(`heat_areas.${index}` as never) as any;
    const currentType = newType || currentValues?.wbgt_type || "in";
    const db = Number(currentValues?.db_temp);
    const wb = Number(currentValues?.wb_temp);
    const gt = Number(currentValues?.gt_temp);

    if (wb && gt && !isNaN(wb) && !isNaN(gt)) {
      let calculated = 0;
      if (currentType === "in") {
        calculated = 0.7 * wb + 0.3 * gt;
      } else if (currentType === "out" && db && !isNaN(db)) {
        calculated = 0.7 * wb + 0.2 * gt + 0.1 * db;
      }

      if (calculated > 0) {
        setValue(
          `heat_areas.${index}.wbgt_avg` as never,
          Number(calculated.toFixed(1)) as never,
          { shouldValidate: true },
        );
      }
    }
  };

  useStepDraft(watch, "answers");
  return (
    <form
      onSubmit={handleSubmit(onNext, focusFormError)}
      className="animate-fade-in flex flex-col gap-6"
      noValidate
    >
      {category === "noise" && (
        <div className="form-section-card p-5">
          <h3 className="text-card-title text-text-primary mb-4 font-semibold">
            แบบฟอร์มบันทึกการตรวจวัด ({ASSESSMENT_CATEGORY_LABELS[category]})
          </h3>
          <div className="flex flex-col gap-4">
            <Controller
              name="standard_value"
              control={control}
              render={({ field }) => (
                <FormSelect
                  label={`มาตรฐาน (${unitLabel})`}
                  placeholder="-- เลือกมาตรฐาน --"
                  options={standards.map((std) => ({
                    value: std.value.toString(),
                    label: std.label,
                  }))}
                  required
                  {...field}
                  value={
                    field.value !== undefined ? field.value.toString() : ""
                  }
                  error={errors.standard_value?.message}
                />
              )}
            />
          </div>
        </div>
      )}

      <div className="form-section-card p-5">
        <h3 className="text-card-title text-text-primary mb-4 flex items-center justify-between font-semibold">
          <span>ค่าที่ตรวจวัดได้ ({unitLabel})</span>
          {category !== "noise" && average !== null && (
            <span className="text-small text-primary bg-primary-soft rounded-full px-3 py-1 font-normal">
              ค่าเฉลี่ย: {average} {unitLabel}
            </span>
          )}
        </h3>

        {category === "noise" && (
          <div className="flex flex-col gap-6">
            <p className="text-caption text-text-secondary -mt-2">
              ระบุสถานที่/ลักษณะงาน ระดับเสียงต่ำสุด สูงสุด เฉลี่ย
              และเลือกมาตรฐานเฉพาะจุด
            </p>

            <div className="flex flex-col gap-4">
              {noiseFields.map((field, index) => (
                <div
                  key={field.id}
                  className="border-border bg-background animate-scale-in relative grid grid-cols-1 gap-4 rounded-lg border p-4 pt-10 shadow-sm md:grid-cols-2"
                >
                  <div className="text-small text-text-primary absolute top-3 left-4 font-semibold">
                    จุดตรวจที่ {index + 1}
                  </div>
                  {noiseFields.length > 1 && (
                    <button
                      type="button"
                      onClick={() => removeNoise(index)}
                      className="text-danger hover:text-danger-hover hover:bg-danger-soft absolute top-2 right-2 rounded-full p-1.5 transition-colors"
                      title="ลบจุดตรวจ"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  )}

                  <FormInput
                    label="สถานที่ / ลักษณะงาน"
                    placeholder="เช่น โซนเครื่องจักร"
                    required
                    {...register(`noise_areas.${index}.location_desc` as never)}
                    error={noiseErrors?.[index]?.location_desc?.message}
                  />

                  <FormInput
                    label="ระดับเสียงต่ำสุด (dBA)"
                    type="number"
                    inputMode="decimal"
                    step="0.1"
                    placeholder="ระบุค่าต่ำสุด"
                    required
                    {...register(`noise_areas.${index}.min_dBA` as never)}
                    error={noiseErrors?.[index]?.min_dBA?.message}
                  />

                  <FormInput
                    label="ระดับเสียงสูงสุด (dBA)"
                    type="number"
                    inputMode="decimal"
                    step="0.1"
                    placeholder="ระบุค่าสูงสุด"
                    required
                    {...register(`noise_areas.${index}.max_dBA` as never)}
                    error={noiseErrors?.[index]?.max_dBA?.message}
                  />

                  <FormInput
                    label="ระดับเสียงเฉลี่ย (dBA)"
                    type="number"
                    inputMode="decimal"
                    step="0.1"
                    placeholder="ระบุค่าเฉลี่ย"
                    required
                    {...register(`noise_areas.${index}.avg_dBA` as never)}
                    error={noiseErrors?.[index]?.avg_dBA?.message}
                  />

                  <FormInput
                    label="หมายเหตุ"
                    placeholder="เช่น ข้อมูลเพิ่มเติม (ถ้ามี)"
                    {...register(`noise_areas.${index}.remark` as never)}
                    error={noiseErrors?.[index]?.remark?.message}
                  />
                </div>
              ))}
            </div>

            <Button
              type="button"
              variant="outline"
              className="text-text-secondary hover:text-primary hover:border-primary hover:bg-primary-soft/30 flex w-full items-center justify-center gap-2 border-2 border-dashed py-6 transition-all"
              onClick={() =>
                appendNoise({
                  location_desc: "",
                  min_dBA: undefined as any,
                  max_dBA: undefined as any,
                  avg_dBA: undefined as any,
                  remark: "",
                } as never)
              }
            >
              <PlusCircle className="h-5 w-5" />
              เพิ่มจุดตรวจ
            </Button>
          </div>
        )}

        {category === "light" && (
          <div className="flex flex-col gap-6">
            <p className="text-caption text-text-secondary -mt-2">
              ระบุสถานที่/ลักษณะงาน ค่ามาตรฐานเฉพาะจุด และค่าความสว่างที่วัดได้
            </p>

            <div className="flex flex-col gap-4">
              {lightFields.map((field, index) => (
                <div
                  key={field.id}
                  className="border-border bg-background animate-scale-in relative grid grid-cols-1 gap-4 rounded-lg border p-4 pt-10 shadow-sm md:grid-cols-2"
                >
                  <div className="text-small text-text-primary absolute top-3 left-4 font-semibold">
                    จุดตรวจที่ {index + 1}
                  </div>
                  {lightFields.length > 1 && (
                    <button
                      type="button"
                      onClick={() => removeLight(index)}
                      className="text-danger hover:text-danger-hover hover:bg-danger-soft absolute top-2 right-2 rounded-full p-1.5 transition-colors"
                      title="ลบจุดตรวจ"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  )}

                  <FormInput
                    label="สถานที่ / ลักษณะงาน"
                    placeholder="เช่น โต๊ะปฏิบัติงานหน้าคอม"
                    required
                    {...register(`light_areas.${index}.location_desc` as never)}
                    error={lightErrors?.[index]?.location_desc?.message}
                  />

                  <Controller
                    name={`light_areas.${index}.standard_value` as never}
                    control={control}
                    render={({ field: selectField }) => (
                      <FormSelect
                        label="ค่ามาตรฐาน (Lux)"
                        placeholder="-- เลือกมาตรฐานเฉพาะจุด --"
                        options={LIGHT_POINT_STANDARDS.map((std) => ({
                          value: std.value.toString(),
                          label: std.label,
                        }))}
                        required
                        {...selectField}
                        value={
                          selectField.value !== undefined &&
                          selectField.value !== null
                            ? String(selectField.value)
                            : ""
                        }
                        error={lightErrors?.[index]?.standard_value?.message}
                      />
                    )}
                  />

                  <FormInput
                    label={`ผลการตรวจวัด (${unitLabel})`}
                    type="number"
                    inputMode="decimal"
                    step="0.1"
                    placeholder={`ระบุค่า ${unitLabel}`}
                    required
                    {...register(`light_areas.${index}.measure` as never)}
                    error={lightErrors?.[index]?.measure?.message}
                  />

                  <FormInput
                    label="หมายเหตุ"
                    placeholder="เช่น ระบุข้อมูลเพิ่มเติม (ถ้ามี)"
                    {...register(`light_areas.${index}.remark` as never)}
                    error={lightErrors?.[index]?.remark?.message}
                  />
                </div>
              ))}
            </div>

            <Button
              type="button"
              variant="outline"
              className="text-text-secondary hover:text-primary hover:border-primary hover:bg-primary-soft/30 flex w-full items-center justify-center gap-2 border-2 border-dashed py-6 transition-all"
              onClick={() =>
                appendLight({
                  location_desc: "",
                  standard_value: 300,
                  measure: undefined as any,
                  remark: "",
                } as never)
              }
            >
              <PlusCircle className="h-5 w-5" />
              เพิ่มจุดตรวจ
            </Button>
          </div>
        )}

        {category === "heat" && (
          <div className="flex flex-col gap-6">
            <p className="text-caption text-text-secondary -mt-2">
              ระบุข้อมูลการตรวจวัดความร้อน ค่า WBGT และระดับภาระงานในแต่ละจุด
            </p>

            <div className="flex flex-col gap-4">
              {heatFields.map((field, index) => (
                <div
                  key={field.id}
                  className="border-border bg-background animate-scale-in relative flex flex-col gap-4 rounded-lg border p-4 pt-10 shadow-sm"
                >
                  <div className="text-small text-text-primary absolute top-3 left-4 font-semibold">
                    จุดตรวจที่ {index + 1}
                  </div>
                  {heatFields.length > 1 && (
                    <button
                      type="button"
                      onClick={() => removeHeat(index)}
                      className="text-danger hover:text-danger-hover hover:bg-danger-soft absolute top-2 right-2 rounded-full p-1.5 transition-colors"
                      title="ลบจุดตรวจ"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  )}

                  <FormInput
                    label="สถานที่ / แผนกตรวจวัด"
                    placeholder="เช่น โรงซักฟอก"
                    required
                    {...register(`heat_areas.${index}.location_desc` as never)}
                    error={heatErrors?.[index]?.location_desc?.message}
                  />

                  <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                    <FormInput
                      label="เวลาเริ่มต้น (HH:MM)"
                      type="time"
                      required
                      {...register(`heat_areas.${index}.start_time` as never)}
                      error={heatErrors?.[index]?.start_time?.message}
                    />
                    <FormInput
                      label="เวลาสิ้นสุด (HH:MM)"
                      type="time"
                      required
                      {...register(`heat_areas.${index}.end_time` as never)}
                      error={heatErrors?.[index]?.end_time?.message}
                    />
                  </div>

                  <Controller
                    name={`heat_areas.${index}.wbgt_type` as never}
                    control={control}
                    render={({ field: typeField }) => (
                      <FormSelect
                        label="ประเภทพื้นที่ (WBGT)"
                        placeholder="-- เลือกประเภท --"
                        options={[
                          { value: "in", label: "ในอาคาร (WBGT in)" },
                          { value: "out", label: "นอกอาคาร (WBGT out)" },
                        ]}
                        {...typeField}
                        value={typeField.value || "in"}
                        onChange={(e) => {
                          typeField.onChange(e);
                          calculateAndSetWBGT(index, e.target.value);
                        }}
                      />
                    )}
                  />

                  <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
                    <FormInput
                      label="อุณหภูมิกระเปาะแห้ง DB (°C)"
                      type="number"
                      inputMode="decimal"
                      step="0.1"
                      placeholder="ไม่บังคับ"
                      {...register(`heat_areas.${index}.db_temp` as never)}
                      onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
                        register(
                          `heat_areas.${index}.db_temp` as never,
                        ).onChange(e);
                        calculateAndSetWBGT(index);
                      }}
                      error={heatErrors?.[index]?.db_temp?.message}
                    />
                    <FormInput
                      label="อุณหภูมิกระเปาะเปียก WB (°C)"
                      type="number"
                      inputMode="decimal"
                      step="0.1"
                      placeholder="ไม่บังคับ"
                      {...register(`heat_areas.${index}.wb_temp` as never)}
                      onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
                        register(
                          `heat_areas.${index}.wb_temp` as never,
                        ).onChange(e);
                        calculateAndSetWBGT(index);
                      }}
                      error={heatErrors?.[index]?.wb_temp?.message}
                    />
                    <FormInput
                      label="อุณหภูมิโกลบ GT (°C)"
                      type="number"
                      inputMode="decimal"
                      step="0.1"
                      placeholder="ไม่บังคับ"
                      {...register(`heat_areas.${index}.gt_temp` as never)}
                      onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
                        register(
                          `heat_areas.${index}.gt_temp` as never,
                        ).onChange(e);
                        calculateAndSetWBGT(index);
                      }}
                      error={heatErrors?.[index]?.gt_temp?.message}
                    />
                  </div>

                  <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
                    <Controller
                      name={`heat_areas.${index}.wbgt_in` as never}
                      control={control}
                      render={({ field: wbgtInField }) => (
                        <FormInput
                          label="ค่า WBGT จากเครื่องวัด (°C)"
                          type="number"
                          inputMode="decimal"
                          step="0.1"
                          placeholder="ไม่บังคับ"
                          {...wbgtInField}
                          value={
                            wbgtInField.value !== undefined &&
                            wbgtInField.value !== null
                              ? String(wbgtInField.value)
                              : ""
                          }
                          onChange={(e) => {
                            wbgtInField.onChange(e);
                            if (e.target.value !== "") {
                              setValue(
                                `heat_areas.${index}.wbgt_avg` as never,
                                e.target.value as never,
                                { shouldValidate: true },
                              );
                            }
                          }}
                          error={heatErrors?.[index]?.wbgt_in?.message}
                        />
                      )}
                    />

                    <Controller
                      name={`heat_areas.${index}.workload` as never}
                      control={control}
                      render={({ field: selectField }) => (
                        <FormSelect
                          label="ประเภทงาน"
                          placeholder="-- เลือกประเภทงาน --"
                          options={HEAT_WORKLOADS}
                          required
                          {...selectField}
                          value={
                            selectField.value !== undefined &&
                            selectField.value !== null
                              ? String(selectField.value)
                              : ""
                          }
                          onChange={(e) => {
                            selectField.onChange(e);
                            const val = e.target.value;
                            const std =
                              HEAT_STANDARDS[
                                val as keyof typeof HEAT_STANDARDS
                              ];
                            if (std) {
                              setValue(
                                `heat_areas.${index}.standard_value` as never,
                                std.value as never,
                                { shouldValidate: true },
                              );
                            }
                          }}
                          error={heatErrors?.[index]?.workload?.message}
                        />
                      )}
                    />

                    <FormInput
                      label="มาตรฐาน (°C)"
                      type="number"
                      inputMode="decimal"
                      step="0.1"
                      placeholder="อิงจากประเภทงาน"
                      required
                      {...register(
                        `heat_areas.${index}.standard_value` as never,
                      )}
                      error={heatErrors?.[index]?.standard_value?.message}
                    />

                    <FormInput
                      label="ค่า WBGT เฉลี่ย (°C)"
                      type="number"
                      inputMode="decimal"
                      step="0.1"
                      placeholder="บังคับระบุ"
                      required
                      {...register(`heat_areas.${index}.wbgt_avg` as never)}
                      error={heatErrors?.[index]?.wbgt_avg?.message}
                    />
                  </div>

                  <FormInput
                    label="หมายเหตุ"
                    placeholder="เช่น ข้อมูลเพิ่มเติม (ถ้ามี)"
                    {...register(`heat_areas.${index}.remark` as never)}
                    error={heatErrors?.[index]?.remark?.message}
                  />
                </div>
              ))}
            </div>

            <Button
              type="button"
              variant="outline"
              className="text-text-secondary hover:text-primary hover:border-primary hover:bg-primary-soft/30 flex w-full items-center justify-center gap-2 border-2 border-dashed py-6 transition-all"
              onClick={() =>
                appendHeat({
                  location_desc: "",
                  start_time: "",
                  end_time: "",
                  db_temp: undefined as any,
                  wb_temp: undefined as any,
                  gt_temp: undefined as any,
                  wbgt_in: undefined as any,
                  wbgt_type: "in" as const,
                  workload: "",
                  wbgt_avg: undefined as any,
                  standard_value: undefined as any,
                  remark: "",
                } as never)
              }
            >
              <PlusCircle className="h-5 w-5" />
              เพิ่มจุดตรวจ
            </Button>
          </div>
        )}
      </div>

      <div className="mt-2 flex gap-3 pb-8">
        <Button
          type="button"
          variant="outline"
          className="flex-1"
          onClick={onPrev}
        >
          ย้อนกลับ
        </Button>
        <Button type="submit" className="flex-1">
          สรุปผลการประเมิน
        </Button>
      </div>
    </form>
  );
}

"use client";
import { focusFormError } from "@/lib/v3/form-errors";
import { useStepDraft } from "@/hooks/use-step-draft";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import {
  healthRiskMeasurementSchema,
  type HealthRiskMeasurementFormValues,
} from "@/lib/health-risk-schema";
import {
  HEALTH_RISK_QUESTIONS,
  HEALTH_RISK_OPTIONS,
} from "@/lib/health-risk-data";
import { Button } from "@/components/ui";
import type { AssessmentCategory } from "@/types";
import { ASSESSMENT_CATEGORY_LABELS } from "@/lib/constants";
import { cn } from "@/lib/utils";

interface HealthRiskStepProps {
  category: AssessmentCategory;
  defaultValues?: Partial<HealthRiskMeasurementFormValues>;
  onNext: (data: HealthRiskMeasurementFormValues) => void;
  onPrev: () => void;
}

export function HealthRiskStep({
  category,
  defaultValues,
  onNext,
  onPrev,
}: HealthRiskStepProps) {
  const {
    register,
    watch,
    handleSubmit,
    formState: { errors, isValid },
  } = useForm<HealthRiskMeasurementFormValues>({
    resolver: zodResolver(healthRiskMeasurementSchema),
    defaultValues: {
      q1: undefined,
      q2: undefined,
      q3: undefined,
      q4: undefined,
      q5: undefined,
      q6: undefined,
      q7: undefined,
      q8: undefined,
      q9: undefined,
      q10: undefined,
      ...defaultValues,
    } as any,
    mode: "onTouched",
  });

  const questions =
    HEALTH_RISK_QUESTIONS[category as keyof typeof HEALTH_RISK_QUESTIONS] || [];

  useStepDraft(watch, "answers");
  return (
    <form
      onSubmit={handleSubmit(onNext, focusFormError)}
      className="animate-fade-in flex flex-col gap-6"
      noValidate
    >
      <div className="form-section-card p-5">
        <h3 className="text-card-title text-text-primary mb-2 font-semibold">
          แบบประเมินอาการทางสุขภาพ ({ASSESSMENT_CATEGORY_LABELS[category]})
        </h3>
        <p className="text-caption text-text-secondary mb-6">
          โปรดเลือกคำตอบที่ตรงกับอาการของท่านมากที่สุดในแต่ละข้อ
          (บังคับตอบทุกข้อ)
        </p>

        <div className="flex flex-col gap-5">
          {questions.map((q, index) => {
            const fieldName =
              `q${index + 1}` as keyof HealthRiskMeasurementFormValues;
            const errorMsg = errors[fieldName]?.message;
            return (
              <div
                key={q.id}
                className={cn(
                  "flex flex-col gap-3 rounded-lg border p-4 transition-colors",
                  errorMsg
                    ? "border-danger bg-danger-soft/10"
                    : "border-border bg-background",
                )}
              >
                <p className="text-body text-text-primary font-medium">
                  {index + 1}. {q.text} <span className="text-danger">*</span>
                </p>
                <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
                  {HEALTH_RISK_OPTIONS.map((opt) => (
                    <label
                      key={opt.value}
                      className="border-border bg-surface hover:bg-muted has-[:focus-visible]:ring-primary has-[:checked]:border-primary has-[:checked]:bg-primary-tint relative flex cursor-pointer items-center gap-3 rounded-md border px-4 py-3 transition-all active:scale-[0.98] has-[:checked]:shadow-sm has-[:focus-visible]:ring-2"
                    >
                      <input
                        type="radio"
                        value={opt.value}
                        {...register(fieldName)}
                        className="peer sr-only"
                      />
                      {/* Custom radio indicator */}
                      <div className="border-border bg-surface peer-checked:border-primary flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 transition-colors">
                        <div className="bg-primary h-2.5 w-2.5 rounded-full opacity-0 transition-opacity peer-checked:opacity-100" />
                      </div>
                      <span className="text-small text-text-primary peer-checked:text-primary font-medium">
                        {opt.label}
                      </span>
                    </label>
                  ))}
                </div>
                {errorMsg && (
                  <p className="text-caption text-danger mt-1">{errorMsg}</p>
                )}
              </div>
            );
          })}
        </div>
      </div>

      <div className="mt-2 flex gap-3 pb-8">
        <Button
          type="button"
          variant="outline"
          className="flex-1"
          onClick={onPrev}
        >
          ย้อนกลับ
        </Button>
        <Button type="submit" className="flex-1">
          สรุปผลอาการทางสุขภาพ
        </Button>
      </div>
    </form>
  );
}

"use client";
import { focusFormError } from "@/lib/v3/form-errors";
import { useStepDraft } from "@/hooks/use-step-draft";

import { useForm, Controller } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import {
  respondentProfileSchema,
  type RespondentProfileFormValues,
} from "@/lib/schemas";
import { FormInput, FormSelect, RadioCard } from "@/components/forms";
import { Button } from "@/components/ui";
import {
  GENDER_OPTIONS,
  EDUCATION_LEVEL_OPTIONS,
  MARITAL_STATUS_OPTIONS,
} from "@/lib/constants";

interface ProfileStepProps {
  defaultValues?: Partial<RespondentProfileFormValues>;
  onNext: (data: RespondentProfileFormValues) => void;
}

export function ProfileStep({ defaultValues, onNext }: ProfileStepProps) {
  const {
    register,
    handleSubmit,
    control,
    watch,
    formState: { errors, isValid },
  } = useForm<RespondentProfileFormValues>({
    resolver: zodResolver(respondentProfileSchema) as any,
    defaultValues: {
      full_name: "",
      gender: "male",
      age: undefined,
      weight: undefined,
      height: undefined,
      education_level: "",
      marital_status: "",
      has_underlying_disease: false,
      underlying_disease_details: "",
      ...defaultValues,
    } as any,
    mode: "onTouched",
  });

  const hasDisease = watch("has_underlying_disease");

  // Allow resetting form if defaultValues change (e.g. loaded from draft later)

  useStepDraft(watch, "profile");
  return (
    <form
      onSubmit={handleSubmit(onNext, focusFormError)}
      className="animate-fade-in flex flex-col gap-6"
      noValidate
    >
      <div className="form-section-card p-5">
        <h3 className="text-card-title text-text-primary mb-4 font-semibold">
          ข้อมูลส่วนตัว
        </h3>
        <div className="flex flex-col gap-4">
          <FormInput
            label="ชื่อ-นามสกุล"
            placeholder="เช่น สมชาย ใจดี"
            required
            {...register("full_name")}
            error={errors.full_name?.message}
          />

          <Controller
            name="gender"
            control={control}
            render={({ field }) => (
              <FormSelect
                label="เพศ"
                placeholder="เลือกเพศ"
                options={[...GENDER_OPTIONS]}
                required
                {...field}
                error={errors.gender?.message}
              />
            )}
          />

          <FormInput
            label="อายุ (ปี)"
            type="number"
            inputMode="numeric"
            placeholder="ตัวเลขเท่านั้น"
            required
            {...register("age")}
            error={errors.age?.message}
          />

          <div className="grid grid-cols-2 gap-4">
            <FormInput
              label="น้ำหนัก (กก.)"
              type="number"
              inputMode="decimal"
              step="0.1"
              placeholder="ไม่บังคับ"
              {...register("weight")}
              error={errors.weight?.message}
            />
            <FormInput
              label="ส่วนสูง (ซม.)"
              type="number"
              inputMode="decimal"
              step="0.1"
              placeholder="ไม่บังคับ"
              {...register("height")}
              error={errors.height?.message}
            />
          </div>

          <Controller
            name="education_level"
            control={control}
            render={({ field }) => (
              <FormSelect
                label="ระดับการศึกษา"
                placeholder="เลือกระดับการศึกษา (ไม่บังคับ)"
                options={[...EDUCATION_LEVEL_OPTIONS]}
                {...field}
                error={errors.education_level?.message}
              />
            )}
          />

          <Controller
            name="marital_status"
            control={control}
            render={({ field }) => (
              <FormSelect
                label="สถานภาพ"
                placeholder="เลือกสถานภาพ (ไม่บังคับ)"
                options={[...MARITAL_STATUS_OPTIONS]}
                {...field}
                error={errors.marital_status?.message}
              />
            )}
          />
        </div>
      </div>

      <div className="form-section-card p-5">
        <h3 className="text-card-title text-text-primary mb-4 font-semibold">
          ข้อมูลสุขภาพ
        </h3>
        <div className="flex flex-col gap-4">
          <div>
            <label className="text-small text-text-primary mb-2 block font-medium">
              ท่านมีโรคประจำตัวหรือไม่? <span className="text-danger">*</span>
            </label>
            <div className="grid grid-cols-2 gap-3">
              <Controller
                name="has_underlying_disease"
                control={control}
                render={({ field }) => (
                  <>
                    <RadioCard
                      label="ไม่มี"
                      checked={field.value === false}
                      onChange={() => field.onChange(false)}
                    />
                    <RadioCard
                      label="มี"
                      checked={field.value === true}
                      onChange={() => field.onChange(true)}
                    />
                  </>
                )}
              />
            </div>
            {errors.has_underlying_disease && (
              <p className="text-caption text-danger mt-1">
                {errors.has_underlying_disease.message}
              </p>
            )}
          </div>

          {hasDisease && (
            <div className="animate-fade-in">
              <FormInput
                label="ระบุโรคประจำตัว"
                placeholder="เช่น เบาหวาน, ความดัน"
                required
                {...register("underlying_disease_details")}
                error={errors.underlying_disease_details?.message}
              />
            </div>
          )}
        </div>
      </div>

      <div className="mt-2 pb-8">
        <Button type="submit" className="w-full">
          ถัดไป
        </Button>
      </div>
    </form>
  );
}

"use client";

import { useState } from "react";
import {
  CheckCircle2,
  XCircle,
  AlertTriangle,
  Star,
  FileText,
  Eye,
  ExternalLink,
  Info,
  X,
} from "lucide-react";
import { Button, ImageLightboxModal } from "@/components/ui";
import { AssessmentDraftData } from "@/lib/schemas";
import {
  calculateAverage,
  evaluateEnvironmentResult,
  LIGHT_POINT_STANDARDS,
  NOISE_STANDARDS,
  HEAT_STANDARDS,
  HEAT_WORKLOADS,
} from "@/lib/environment-schema";
import {
  calculateHealthRiskScore,
  evaluateHealthRiskResult,
} from "@/lib/health-risk-schema";
import { calculateSatisfactionResult } from "@/lib/satisfaction-schema";
import {
  EDUCATION_LEVEL_OPTIONS,
  GENDER_OPTIONS,
  MARITAL_STATUS_OPTIONS,
  POSITION_TYPE_OPTIONS,
} from "@/lib/constants";
import type { AssessmentCategory } from "@/types";
import { cn, formatFileSize } from "@/lib/utils";

interface ReviewStepProps {
  type?: "environment" | "health_risk" | "satisfaction";
  category?: AssessmentCategory;
  draftData: AssessmentDraftData;
  isSubmitting: boolean;
  onSubmit: () => void;
  onPrev: () => void;
}

export function ReviewStep({
  type = "environment",
  category,
  draftData,
  isSubmitting,
  onSubmit,
  onPrev,
}: ReviewStepProps) {
  const profile = draftData.profile;
  const workInfo = draftData.workInfo;
  const inspectionData = draftData.inspectionData;
  const layoutFile = draftData.layoutFile;
  const answers = draftData.answers as any;

  const optionLabel = (
    options: readonly { value: string; label: string }[],
    value?: string,
  ) => options.find((option) => option.value === value)?.label || value || "-";

  const [previewImage, setPreviewImage] = useState<string | null>(null);

  // Environment Evaluation Variables
  let envEvaluation = null;
  let envAverage = 0;
  const unitLabel =
    category === "light" ? "Lux" : category === "noise" ? "dBA" : "°C";

  // Health Risk Evaluation Variables
  let hrEvaluation = null;

  // Satisfaction Evaluation Variables
  let satisfactionResult = null;

  // Light points processed data for report table
  let processedLightPoints: Array<{
    pointNo: number;
    location_desc: string;
    measure: number;
    standard_display: string;
    isPass: boolean;
    remark: string;
  }> = [];

  // Noise points processed data for report table
  let processedNoisePoints: Array<{
    pointNo: number;
    location_desc: string;
    min_dBA: number;
    max_dBA: number;
    avg_dBA: number;
    standard_display: string;
    isPass: boolean;
    remark: string;
  }> = [];

  // Heat points processed data for report table
  let processedHeatPoints: Array<{
    pointNo: number;
    location_desc: string;
    start_time: string;
    end_time: string;
    total_time: string;
    db_temp: number | "-";
    wb_temp: number | "-";
    gt_temp: number | "-";
    wbgt_in: number | "-";
    wbgt_type: string;
    workload_label: string;
    wbgt_avg: number;
    standard_value: number;
    isPass: boolean;
    remark: string;
  }> = [];

  if (answers) {
    if (type === "environment" && category) {
      if (category === "noise") {
        if (answers.noise_areas && Array.isArray(answers.noise_areas)) {
          let totalPass = 0;
          const vals: number[] = [];

          processedNoisePoints = answers.noise_areas.map(
            (pt: any, index: number) => {
              const avgVal = Number(pt.avg_dBA) || 0;
              vals.push(avgVal);

              const stdObj = NOISE_STANDARDS.find(
                (s) => s.value === Number(answers.standard_value)
              );
              const stdDisplay = stdObj
                ? stdObj.value.toString()
                : answers.standard_value?.toString() || "-";

              const maxStd = Number(answers.standard_value) || 0;
              const isPass = maxStd > 0 ? avgVal <= maxStd : true;
              if (isPass) totalPass++;

              return {
                pointNo: index + 1,
                location_desc: pt.location_desc || "-",
                min_dBA: Number(pt.min_dBA) || 0,
                max_dBA: Number(pt.max_dBA) || 0,
                avg_dBA: avgVal,
                standard_display: stdDisplay,
                isPass,
                remark: pt.remark || "",
              };
            }
          );

          if (vals.length > 0) {
            const sum = vals.reduce((acc, curr) => acc + curr, 0);
            envAverage = Number((sum / vals.length).toFixed(2));
            const allPass = totalPass === processedNoisePoints.length;

            envEvaluation = {
              isPass: allPass,
              score: 0,
              message: allPass
                ? "ระดับเสียงภาพรวมผ่านเกณฑ์มาตรฐาน ควรรักษาสภาพแวดล้อมให้คงเดิม"
                : "ระดับเสียงภาพรวมเกินมาตรฐานที่กำหนด ควรจัดหาอุปกรณ์ป้องกันเสียง (PPE) ให้พนักงานหรือลดแหล่งกำเนิดเสียง",
              calculatedValue: envAverage,
            };
          }
        }
      } else if (category === "heat") {
        if (answers.heat_areas && Array.isArray(answers.heat_areas)) {
          let totalPass = 0;
          const vals: number[] = [];

          processedHeatPoints = answers.heat_areas.map(
            (pt: any, index: number) => {
              const wbgtAvg = Number(pt.wbgt_avg) || 0;
              vals.push(wbgtAvg);

              const workloadObj = HEAT_WORKLOADS.find((w) => w.value === pt.workload);
              const workloadLabel = workloadObj ? workloadObj.label : pt.workload;
              const standard = pt.standard_value !== undefined && pt.standard_value !== null 
                ? Number(pt.standard_value) 
                : (HEAT_STANDARDS[pt.workload as keyof typeof HEAT_STANDARDS]?.value || 0);

              const isPass = standard > 0 ? wbgtAvg <= standard : true;
              if (isPass) totalPass++;

              // Calculate total time
              let totalTime = "-";
              if (pt.start_time && pt.end_time) {
                const [startH, startM] = pt.start_time.split(":").map(Number);
                const [endH, endM] = pt.end_time.split(":").map(Number);
                const diffMins = (endH * 60 + endM) - (startH * 60 + startM);
                if (diffMins > 0) {
                  totalTime = `${diffMins} น.`;
                }
              }

              return {
                pointNo: index + 1,
                location_desc: pt.location_desc || "-",
                start_time: pt.start_time || "-",
                end_time: pt.end_time || "-",
                total_time: totalTime,
                db_temp: pt.db_temp !== undefined && pt.db_temp !== null && pt.db_temp !== "" ? Number(pt.db_temp) : "-",
                wb_temp: pt.wb_temp !== undefined && pt.wb_temp !== null && pt.wb_temp !== "" ? Number(pt.wb_temp) : "-",
                gt_temp: pt.gt_temp !== undefined && pt.gt_temp !== null && pt.gt_temp !== "" ? Number(pt.gt_temp) : "-",
                wbgt_in: pt.wbgt_in !== undefined && pt.wbgt_in !== null && pt.wbgt_in !== "" ? Number(pt.wbgt_in) : "-",
                wbgt_type: pt.wbgt_type || "in",
                workload_label: workloadLabel,
                wbgt_avg: wbgtAvg,
                standard_value: standard,
                isPass,
                remark: pt.remark || "",
              };
            }
          );

          if (vals.length > 0) {
            const sum = vals.reduce((acc, curr) => acc + curr, 0);
            envAverage = Number((sum / vals.length).toFixed(2));
            const allPass = totalPass === processedHeatPoints.length;

            envEvaluation = {
              isPass: allPass,
              score: 0,
              message: allPass
                ? "ระดับความร้อนทุกจุดตรวจวัดอยู่ในเกณฑ์ปลอดภัย"
                : "ระดับความร้อนเกินมาตรฐาน ควรจัดเวลาพักหรือเพิ่มการระบายอากาศในพื้นที่ทำงาน",
              calculatedValue: envAverage,
            };
          }
        }
      } else if (category === "light") {
        if (answers.light_areas && Array.isArray(answers.light_areas)) {
          let totalPass = 0;
          const vals: number[] = [];

          processedLightPoints = answers.light_areas.map(
            (pt: any, index: number) => {
              const measureVal = Number(pt.measure) || 0;
              vals.push(measureVal);

              const stdObj = LIGHT_POINT_STANDARDS.find(
                (s) => s.value === Number(pt.standard_value)
              );
              const stdDisplay = stdObj
                ? stdObj.display
                : pt.standard_value?.toString() || "-";
              const minStd = Number(pt.standard_value) || 0;
              const isPass = measureVal >= minStd;
              if (isPass) totalPass++;

              return {
                pointNo: index + 1,
                location_desc: pt.location_desc || "-",
                measure: measureVal,
                standard_display: stdDisplay,
                isPass,
                remark: pt.remark || "",
              };
            }
          );

          if (vals.length > 0) {
            const sum = vals.reduce((acc, curr) => acc + curr, 0);
            envAverage = Number((sum / vals.length).toFixed(2));
            const allPass = totalPass === processedLightPoints.length;

            envEvaluation = {
              isPass: allPass,
              score: 0,
              message: allPass
                ? "ระดับแสงสว่างทุกจุดตรวจวัดผ่านเกณฑ์มาตรฐาน ควรรักษาระดับแสงสว่างให้เพียงพออย่างต่อเนื่อง"
                : `พบจุดตรวจวัดที่ไม่ผ่านเกณฑ์มาตรฐานจำนวน ${
                    processedLightPoints.length - totalPass
                  } จุด ควรเพิ่มหลอดไฟหรือจัดแสงสว่างในพื้นที่ดังกล่าว`,
              calculatedValue: envAverage,
            };
          }
        }
      } else if (answers.standard_value) {
        const avg = calculateAverage(
          answers.measure_1,
          answers.measure_2,
          answers.measure_3
        );
        if (avg !== null) {
          envAverage = avg;
          envEvaluation = evaluateEnvironmentResult(
            envAverage,
            Number(answers.standard_value),
            category
          );
        }
      }
    } else if (type === "health_risk" && answers.q1 !== undefined) {
      const score = calculateHealthRiskScore(answers);
      hrEvaluation = evaluateHealthRiskResult(score, category);
    } else if (type === "satisfaction" && answers.q1 !== undefined) {
      satisfactionResult = calculateSatisfactionResult(answers);
    }
  }

  return (
    <div className="flex flex-col gap-6 animate-fade-in">
      {type !== "satisfaction" && (
        <div className="form-section-card p-5">
        <h3 className="mb-4 text-card-title font-semibold text-text-primary">
          {type === "health_risk"
            ? "ข้อมูลผู้ตอบแบบประเมิน"
            : "ข้อมูลการตรวจวัด"}
        </h3>

        {type === "environment" ? (
          inspectionData ? (
            <div className="flex flex-col gap-2 text-small text-text-secondary">
              <div className="flex justify-between border-b border-border py-2">
                <span>ชื่อ-นามสกุลผู้ตรวจ</span>
                <span className="font-medium text-text-primary">
                  {inspectionData.inspector_name}
                </span>
              </div>
              <div className="flex justify-between border-b border-border py-2">
                <span>ตำแหน่ง</span>
                <span className="font-medium text-text-primary">
                  {inspectionData.position}
                </span>
              </div>
              <div className="flex justify-between border-b border-border py-2">
                <span>สถานที่ตรวจ</span>
                <span className="font-medium text-text-primary">
                  {inspectionData.inspection_location}
                </span>
              </div>
              <div className="flex justify-between border-b border-border py-2">
                <span>วันที่ทำการตรวจวัด</span>
                <span className="font-medium text-text-primary">
                  {inspectionData.inspection_date}
                </span>
              </div>
              <div className="flex justify-between border-b border-border py-2">
                <span>เครื่องมือที่ใช้</span>
                <span className="font-medium text-text-primary">
                  {inspectionData.equipment}
                </span>
              </div>
              <div className="flex justify-between py-2">
                <span>ช่วงเวลาที่ตรวจวัด</span>
                <span className="font-medium text-text-primary">
                  {inspectionData.start_time} - {inspectionData.end_time} น.
                </span>
              </div>

              {/* Room Layout Attachment Section */}
              <div className="mt-3 border-t border-border pt-3">
                <div className="flex items-center justify-between mb-2">
                  <span className="font-medium text-text-primary">ผังพื้นที่ห้อง (Layout)</span>
                  {layoutFile ? (
                    <span className="rounded-full bg-emerald-50 border border-emerald-200/60 px-2 py-0.5 text-[11px] font-medium text-emerald-700">
                      แนบแล้ว
                    </span>
                  ) : (
                    <span className="rounded-full bg-amber-50 border border-amber-200/60 px-2 py-0.5 text-[11px] font-medium text-amber-700">
                      ยังไม่ได้แนบ
                    </span>
                  )}
                </div>

                {layoutFile ? (
                  <div className="flex items-center gap-3 rounded-lg border border-gray-200/80 bg-white/70 p-3">
                    {layoutFile.fileType.startsWith("image/") ? (
                      <div
                        onClick={() => setPreviewImage(layoutFile.fileData)}
                        className="relative h-12 w-12 shrink-0 cursor-pointer overflow-hidden rounded-md border border-gray-200 bg-gray-100 group"
                        title="คลิกเพื่อดูรูปขยาย"
                      >
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img
                          src={layoutFile.fileData}
                          alt={layoutFile.fileName}
                          className="h-full w-full object-cover group-hover:scale-105 transition-transform"
                        />
                      </div>
                    ) : (
                      <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-md bg-red-50 text-red-500 border border-red-100">
                        <FileText className="h-6 w-6" />
                      </div>
                    )}
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-caption font-medium text-text-primary">
                        {layoutFile.fileName}
                      </p>
                      <p className="text-[11px] text-text-tertiary">
                        {formatFileSize(layoutFile.fileSize)}
                      </p>
                    </div>
                    {layoutFile.fileType.startsWith("image/") ? (
                      <button
                        type="button"
                        onClick={() => setPreviewImage(layoutFile.fileData)}
                        className="inline-flex items-center gap-1 text-caption text-primary hover:underline"
                      >
                        <Eye className="h-3.5 w-3.5" />
                        ดูรูป
                      </button>
                    ) : (
                      <button
                        type="button"
                        onClick={() => {
                          const win = window.open();
                          if (win) {
                            win.document.write(
                              `<iframe src="${layoutFile.fileData}" frameborder="0" style="border:0; width:100%; height:100%;" allowfullscreen></iframe>`
                            );
                            win.document.title = layoutFile.fileName;
                          }
                        }}
                        className="inline-flex items-center gap-1 text-caption text-primary hover:underline"
                      >
                        <ExternalLink className="h-3.5 w-3.5" />
                        เปิดดู
                      </button>
                    )}
                  </div>
                ) : (
                  <div className="flex items-center gap-2 rounded-lg bg-amber-50/70 border border-amber-200/60 p-2.5 text-caption text-amber-800">
                    <Info className="h-4 w-4 shrink-0 text-amber-600" />
                    <span>ยังไม่ได้แนบผังห้อง (สามารถอัปโหลดเพิ่มเติมในหน้ารายงานผลได้)</span>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <p className="text-small text-danger">ข้อมูลไม่สมบูรณ์</p>
          )
        ) : profile && workInfo ? (
          <div className="text-small text-text-secondary flex flex-col gap-5">
            <section>
              <h4 className="text-text-primary mb-1 font-semibold">
                ข้อมูลส่วนตัวและสุขภาพ
              </h4>
              {[
                ["ชื่อ-นามสกุล", profile.full_name],
                ["เพศ", optionLabel(GENDER_OPTIONS, profile.gender)],
                ["อายุ", profile.age ? `${profile.age} ปี` : "-"],
                ["น้ำหนัก", profile.weight ? `${profile.weight} กก.` : "-"],
                ["ส่วนสูง", profile.height ? `${profile.height} ซม.` : "-"],
                [
                  "ระดับการศึกษา",
                  optionLabel(EDUCATION_LEVEL_OPTIONS, profile.education_level),
                ],
                [
                  "สถานภาพ",
                  optionLabel(MARITAL_STATUS_OPTIONS, profile.marital_status),
                ],
                [
                  "โรคประจำตัว",
                  profile.has_underlying_disease
                    ? profile.underlying_disease_details || "มี"
                    : "ไม่มี",
                ],
              ].map(([label, value]) => (
                <div
                  key={label}
