  } = useForm<WorkInfoFormValues>({
    resolver: zodResolver(workInfoSchema),
    defaultValues: {
      position_type: "",
      department: "",
      work_experience_years: undefined,
      working_hours_per_day: undefined,
      working_days_per_week: undefined,
      ...defaultValues,
    },
    mode: "onTouched",
  });

  useStepDraft(watch, "workInfo");
  return (
    <form
      onSubmit={handleSubmit(onNext, focusFormError)}
      className="animate-fade-in flex flex-col gap-6"
      noValidate
    >
      <div className="form-section-card p-5">
        <h3 className="text-card-title text-text-primary mb-4 font-semibold">
          ข้อมูลการปฏิบัติงาน
        </h3>
        <div className="flex flex-col gap-4">
          <Controller
            name="position_type"
            control={control}
            render={({ field }) => (
              <FormSelect
                label="ประเภทบุคลากร"
                placeholder="เลือกประเภท"
                options={[...POSITION_TYPE_OPTIONS]}
                required
                {...field}
                error={errors.position_type?.message}
              />
            )}
          />

          <FormInput
            label="คณะ / แผนก / ฝ่าย"
            placeholder="ระบุสังกัด"
            required
            {...register("department")}
            error={errors.department?.message}
          />

          <FormInput
            label="อายุงาน (ปี)"
            type="number"
            inputMode="numeric"
            placeholder="ไม่บังคับ"
            {...register("work_experience_years")}
            error={errors.work_experience_years?.message}
          />

          <div className="grid grid-cols-2 gap-4">
            <FormInput
              label="ชั่วโมง/วัน"
              type="number"
              inputMode="numeric"
              placeholder="เวลาทำงาน"
              {...register("working_hours_per_day")}
              error={errors.working_hours_per_day?.message}
            />
            <FormInput
              label="วัน/สัปดาห์"
              type="number"
              inputMode="numeric"
              placeholder="จำนวนวัน"
              {...register("working_days_per_week")}
              error={errors.working_days_per_week?.message}
            />
          </div>
        </div>
      </div>

      <div className="mt-2 flex gap-3 pb-8">
        <Button
          type="button"
          variant="outline"
          className="flex-1"
          onClick={onPrev}
        >
          ย้อนกลับ
        </Button>
        <Button type="submit" className="flex-1">
          ถัดไป
        </Button>
      </div>
    </form>
  );
}

"use client";

