function getOverallLevelLabel(
  level?: string | null,
  isHealthRisk = false,
): string {
  if (level === "pass")
    return isHealthRisk ? "ความเสี่ยงต่ำ (ผ่าน)" : "ผ่านเกณฑ์ (Pass)";
  if (level === "medium")
    return isHealthRisk ? "ความเสี่ยงปานกลาง" : "เสี่ยงปานกลาง (Medium)";
  if (level === "high_risk")
    return isHealthRisk ? "ความเสี่ยงสูง" : "เสี่ยงสูง (High Risk)";
  return "-";
}

/**
