  filename?: string,
) {
  const {
    submissions = [],
    envPointsMap = {},
    hrAnswersMap = {},
    satAnswersMap = {},
  } = data;

  const wb = XLSX.utils.book_new();

  // ----------------------------------------------------
  // Sheet 1: ภาพรวมทั้งหมด (Master Overview)
  // ----------------------------------------------------
  const overviewHeaders = [
    "ลำดับ",
    "วันที่-เวลา",
    "รหัสการประเมิน",
    "ประเภทการประเมิน",
    "หมวดหมู่",
    "ผู้ตรวจ / ผู้ประเมิน",
