    return [
      idx + 1,
      formatDateTimeThai(sub.completed_at || sub.created_at),
      sub.submission_code,
      typeLabel,
      catLabel,
      person,
      loc,
      level,
      sub.overall_score !== null && sub.overall_score !== undefined
